;align-items:center;justify-content:center;text-align:center}.empty-preview>span{display:grid;place-items:center;width:65px;height:65px;border-radius:50%;background:#F8FAE5;border:1px solid #E5DEC9;color:#43766C}.empty-preview h2{font-size:19px;font-weight:800;margin:15px 0 5px}.empty-preview p{margin:0;color:#73685D}.spinning{animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:980px){.reports-layout{grid-template-columns:1fr}.builder-card{height:auto}.report-types{grid-template-columns:1fr 1fr}.preview-card,.empty-preview{min-height:440px}}@media(max-width:600px){.reports-hero,.preview-header{flex-direction:column}.reports-hero .btn{width:100%;justify-content:center}.report-actions{justify-content:flex-start}.report-types{grid-template-columns:1fr}.preview-header,.summary-grid,.table-heading{padding-inline:16px}.save-success{margin-inline:16px;align-items:flex-start;flex-wrap:wrap}.save-success button{width:100%;justify-content:center}}</style>
